/**
 * @param {typeof mockFetchFn} fetchFn
 * @param {() => void} callback
 */
export async function withFetch(fetchFn, callback) {
    mockFetchFn = fetchFn;
    const result = await callback();
    mockFetchFn = null;
    return result;
}

